sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {
    },

    // Funzione Base: Controlla se la data è nel passato
    isDatePast: function(strDate){
        var rightnow = new GlideDateTime();
        var testdate = new GlideDateTime(strDate);

        // Se la data testata è prima di adesso -> True (è passata)
        if (testdate.before(rightnow)) {
            return true;
        }
        else {
            return false;
        }
    },

    // Funzione Challenge: Controlla se la data è OGGI
    isDateToday: function(strDate){
        var rightnow = new GlideDateTime();
        var testdate = new GlideDateTime(strDate);

        // Confrontiamo solo la data (YYYY-MM-DD), ignoriamo l'orario
        var todayDate = rightnow.getLocalDate();
        var checkDate = testdate.getLocalDate();

        // compareTo restituisce 0 se sono uguali
        if(checkDate.compareTo(todayDate) == 0){
            return true;
        }
        return false;
    },

    type: 'NeedItUtils'
};
